import{_ as i,l,o as e,c as s,v as r,p as C,x as t,d as n,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"掩模规则检查 MRC","description":"","frontmatter":{"title":"掩模规则检查 MRC","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mask-rule-check.md","filePath":"litho/mask-rule-check.md","lastUpdated":1789023840000}'),R={name:"litho/mask-rule-check.md"};function d(E,a,c,A,M,m){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="掩模规则检查-mrc" tabindex="-1">掩模规则检查 MRC <a class="header-anchor" href="#掩模规则检查-mrc" aria-label="Permalink to &quot;掩模规则检查 MRC&quot;">​</a></h1><div class="epigraph"><p>光学逆给出的多边形，只有落进掩模厂能写、能蚀、能检的几何集合里，才是一张订单；这个集合叫掩模规则。</p><footer>—— 对照掩模厂（mask shop）对可写性约束与 MRC 的工程通称</footer></div><p><a href="/litho/ilt-regularization">上一课</a>把逆问题的稳定解写成平滑、鲁棒与向可制造集合的投影。缺口是这个集合的语言。掩模厂不读损失函数，只读宽度、间距、面积、jog、尖角——掩模规则检查（Mask Rule Check, MRC）。OPC 或 ILT 若在 MRC 上爆掉，版被拒收，窗口数字作废。本课钉曼哈顿/多边形 MRC。曲线掩模把规则改写成曲率语言，留给<a href="/litho/curvilinear-mrc">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>电子束写入、吸收体蚀刻、缺陷检测，都有最小可分辨的几何。碎片切得太短、衬线太尖、SRAF 太细或太近，光学上可能有益，写入上会变成剂量不足的窄条、蚀刻后断裂、或检测误报。MRC 是掩模厂与晶圆厂之间的合同：最小宽度/间距、最小面积、最小 jog 长度、内角半径、SRAF 打印风险规则等。</p><p>计算光刻若把 MRC 只当优化结束后的过滤器，会在 TAPOUT 前夜发现成千上万违例，再手工或脚本「拍平」，把上一课辛辛苦苦正则掉的窗口又吐回去。缺口是：MRC 必须进迭代（投影或惩罚），而不是事后质检。</p><h3 id="mrc-不是-drc" tabindex="-1">MRC 不是 DRC <a class="header-anchor" href="#mrc-不是-drc" aria-label="Permalink to &quot;MRC 不是 DRC&quot;">​</a></h3><p>设计规则检查（DRC）保证硅上拓扑与库合同：最小晶体管间距、通孔覆盖。MRC 保证<strong>掩模上</strong>的绘制可制造。DRC 干净但 OPC 后 MRC 爆掉，掩模厂仍拒收。两条规则集、两套坐标系（常有 4× 倍率）、两种失败后果。不要把「设计过了 DRC」写成「版能写」。</p><p><span class="marginnote">倍率要把晶圆纳米换成掩模纳米再比规则。High-NA 变形光学两个方向倍率不同，MRC 的「最小宽度」必须按轴声明，不能用一张各向同性表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>规则以掩模厂工艺手册为准：VSB 与多束、二元与衰减、EUV 吸收体厚度，各有一套。计算侧在每次边移动或像素更新后做增量检查，违例则回退、合并碎片、或加惩罚。SRAF 另表：太靠近主图形会印出，太细写不出，落在两堵墙之间。</p><p>签核顺序通常是：DRC → OPC/ILT（内含 MRC 投影）→ 再跑全芯片 MRC → 热区人工或局部再优化。掩模数据准备（断裂成电子束炮或位图）还会引入新的 jog 与缝，二次 MRC 要在断裂之后再跑一次，否则优化器看到的多边形与将要写的几何不是同一张。</p><h3 id="与-epe-的冲突如何仲裁" tabindex="-1">与 EPE 的冲突如何仲裁 <a class="header-anchor" href="#与-epe-的冲突如何仲裁" aria-label="Permalink to &quot;与 EPE 的冲突如何仲裁&quot;">​</a></h3><p>某一碎片为了 EPE 想变窄，MRC 不许。仲裁优先级：不可写则不可出货，EPE 必须改用邻边、助条或放宽设计。把 MRC 权重调到接近零，等于把拒收留给掩模厂——日历上更贵。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>VSB 按矩形炮填充：过窄的条需要过小的成形孔径或过多微炮，剂量与位置误差上升。蚀刻有微负载，孤立细条与密细条的 CD 偏置不同，规则里的「最小宽度」其实是蚀刻后仍不断的宽度。检测算法对直角边训练，尖角和亚分辨率锯齿会触发误报或漏报。MRC 是这三条工艺链在几何上的交集，不是单一光学常数。</p><p>投影到 MRC 集合，会改变掩模频谱的高频。透镜本会滤掉一部分高频，所以「拍平尖角」对空中像的伤害往往小于对写入的伤害——这正是允许（甚至鼓励）丢掉无用锐角的原因。但最小间距若被强制拉大，助条可能失效，窗口真的掉，那是规则与光学的真冲突，要改规则或改照明，而不是再切碎边。</p><p><span class="marginnote">报告「OPC 后 MRC 干净」时写清：是否含断裂后、是否含 SRAF、规则版本对应哪家掩模厂。用 A 厂规则签核、向 B 厂下单，是常见事故。</span></p>',18)),(e(),C(h,null,{default:t(()=>[p(o,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20OPC%5B%22OPC%20%2F%20ILT%20%E6%9B%B4%E6%96%B0%E5%87%A0%E4%BD%95%22%5D%20--%3E%20MRC%5B%22MRC%3A%20%E5%AE%BD%2F%E8%B7%9D%2F%E9%9D%A2%E7%A7%AF%2Fjog%22%5D%0A%20%20MRC%20--%3E%20OK%5B%22%E5%8F%AF%E5%86%99%E5%A4%9A%E8%BE%B9%E5%BD%A2%22%5D%0A%20%20MRC%20--%3E%20BACK%5B%22%E5%9B%9E%E9%80%80%E6%88%96%E5%8A%A0%E6%83%A9%E7%BD%9A%22%5D%0A%20%20OK%20--%3E%20FRAC%5B%22%E6%96%AD%E8%A3%82%20%2F%20%E6%95%B0%E6%8D%AE%E5%87%86%E5%A4%87%22%5D%0A%20%20FRAC%20--%3E%20MRC2%5B%22%E4%BA%8C%E6%AC%A1%20MRC%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>MRC 不保证晶圆 CD，只保证掩模可加工。规则过宽，等于把 RET 的收益剃光；过窄，掩模厂良率崩。规则随写入器世代变，VSB 年代的最小宽度不能直接套到多束曲线上——那是下一课。EUV 吸收体与 DUV 铬/MoSi 的蚀刻偏置不同，不能共用一张 MRC 表。修补（e-beam repair）之后也要再过 MRC，补丁本身可以制造新的 jog 与尖角。</p><p>后课默认：可制造集合已经用多边形 MRC 定义过；曲线还要把「边平行间距」升级成曲率与颈宽。</p><p>规则版本号必须写进掩模订购单，与 OPC 所用投影集合一致。</p><p><span class="marginnote">ILT 正则里的 MRC 投影，若用的是过时规则，会把解投影到一个掩模厂已经不再接受的集合上。规则版本必须进 TAPOUT 合同。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MRC 是掩模厂可写性合同：宽度、间距、面积、jog，不是 DRC。</li><li>必须进入 OPC/ILT 迭代，不能只当前夜过滤器。</li><li>断裂之后要二次检查，写入几何与优化多边形可能不一致。</li><li>与 EPE 冲突时，不可写优先于名义轮廓。</li><li>出处：掩模厂 MRC / 可写性约束的工程通称。</li></ul>',7))])}const P=i(R,[["render",d]]);export{_ as __pageData,P as default};
